// PRIMARY: beacon_node/execution_layer/src/versioned_hashes.rs:beacon_tx_to_tx_envelope (lines 62-68)
pub fn beacon_tx_to_tx_envelope<N: Unsigned>(
    tx: &types::Transaction<N>,
) -> Result<TxEnvelope, Error> {
    let tx_bytes = Vec::from(tx.clone());
    TxEnvelope::decode(&mut tx_bytes.as_slice())
        .map_err(|e| Error::DecodingTransaction(e.to_string()))
}

// RELATED: beacon_node/execution_layer/src/versioned_hashes.rs:extract_versioned_hashes_from_transactions (lines 39-60)
pub fn extract_versioned_hashes_from_transactions<E: EthSpec>(
    transactions: &types::Transactions<E>,
) -> Result<Vec<VersionedHash>, Error> {
    let mut versioned_hashes = Vec::new();
    for tx in transactions {
        if let TxEnvelope::Eip4844(signed_tx_eip4844) = beacon_tx_to_tx_envelope(tx)? {
            versioned_hashes.extend(
                signed_tx_eip4844.tx().tx().blob_versioned_hashes
                    .iter().map(|fb| Hash256::from(fb.0)),
            );
        }
    }
    Ok(versioned_hashes)
}

// PRIMARY: beacon_node/execution_layer/src/versioned_hashes.rs:extract_versioned_hashes_from_transactions (lines 39-60)
pub fn extract_versioned_hashes_from_transactions<E: EthSpec>(
    transactions: &types::Transactions<E>,
) -> Result<Vec<VersionedHash>, Error> {
    let mut versioned_hashes = Vec::new();
    for tx in transactions {
        // TxEnvelope is non-exhaustive so unfortunately we can (no longer) write an exhaustive
        // match here.
        if let TxEnvelope::Eip4844(signed_tx_eip4844) = beacon_tx_to_tx_envelope(tx)? {
            versioned_hashes.extend(
                signed_tx_eip4844.tx().tx().blob_versioned_hashes
                    .iter().map(|fb| Hash256::from(fb.0)),
            );
        }
    }
    Ok(versioned_hashes)
}

